// ============================================================
// Dashboard Lead — Validate & Normalize
// Портировано из DEAL CREATOR / Facebook Form MAIN:
//  - нормализация телефона до +1XXXXXXXXXX + варианты для поиска дублей
//  - ZIP -> штат/таймзона (детерминированная таблица вместо AI-ноды)
//  - разбор "удобного времени связи" -> CALL NOW / Call Scheduled
// ============================================================
const body = $json.body || {};
const S = v => String(v ?? '').trim();

const firstName   = S(body.first_name);
const lastName    = S(body.last_name);
const email       = S(body.email);
const city        = S(body.city);
const zipRaw      = S(body.zip).replace(/[^\d]/g, '').slice(0, 5);
const contactTime = S(body.contact_time);
const source      = S(body.source) || 'Dashboard';
const interest    = S(body.interest);
const notes       = S(body.notes);
const language    = S(body.language);

// --- Валидация обязательных полей ---
const rawPhone  = S(body.phone);
const rawDigits = rawPhone.replace(/\D/g, '');
let error = '';
if (!firstName) error = 'first_name is required';
else if (!rawPhone) error = 'phone is required';
else if (!rawPhone.startsWith('+') && rawDigits.length < 10) error = 'phone must contain at least 10 digits';
else if (rawPhone.startsWith('+') && rawDigits.length < 8) error = 'phone looks too short';
if (error) return [{ json: { valid: false, error } }];

// --- Нормализация телефона (логика DEAL CREATOR) ---
let phone = '', phoneNational = '', isInternational = false;
if (rawPhone.startsWith('+') && !rawPhone.startsWith('+1')) {
  phone = rawPhone.replace(/[^\d+]/g, '');
  isInternational = true;
} else if (rawDigits.length === 10) {
  phoneNational = rawDigits; phone = '+1' + phoneNational;
} else if (rawDigits.length === 11 && rawDigits.startsWith('1')) {
  phoneNational = rawDigits.slice(1); phone = '+1' + phoneNational;
} else if (rawDigits.length > 10) {
  phone = rawPhone.startsWith('+') ? '+' + rawDigits : rawDigits;
  isInternational = true;
} else {
  phone = rawDigits; phoneNational = rawDigits;
}
if (!phoneNational) {
  const d = phone.replace(/\D/g, '');
  phoneNational = d.length >= 10 ? d.slice(-10) : d;
}
const phoneSearchVariants = [];
const addVariant = v => { v = S(v); if (v && !phoneSearchVariants.includes(v)) phoneSearchVariants.push(v); };
addVariant(phone);
if (!isInternational && phoneNational.length === 10) {
  addVariant(phoneNational);
  addVariant('1' + phoneNational);
  addVariant('+1' + phoneNational);
} else {
  addVariant(phone.replace(/\D/g, ''));
}
const phoneSearchRawCriteria = phoneSearchVariants.length === 1
  ? `(Phone:equals:${phoneSearchVariants[0]})`
  : `(${phoneSearchVariants.map(v => `(Phone:equals:${v})`).join('or')})`;
const phoneSearchCriteria = encodeURIComponent(phoneSearchRawCriteria);

// --- ZIP -> штат / таймзона (3-значный префикс, приближённо) ---
const ZIP_RANGES = [
  [5,5,'NY'],[6,9,'PR'],[10,27,'MA'],[28,29,'RI'],[30,38,'NH'],[39,49,'ME'],[50,59,'VT'],
  [60,69,'CT'],[70,89,'NJ'],[100,149,'NY'],[150,196,'PA'],[197,199,'DE'],[200,200,'DC'],
  [201,201,'VA'],[202,205,'DC'],[206,219,'MD'],[220,246,'VA'],[247,268,'WV'],[270,289,'NC'],
  [290,299,'SC'],[300,319,'GA'],[320,349,'FL'],[350,369,'AL'],[370,385,'TN'],[386,397,'MS'],
  [398,399,'GA'],[400,427,'KY'],[430,459,'OH'],[460,479,'IN'],[480,499,'MI'],[500,528,'IA'],
  [530,549,'WI'],[550,567,'MN'],[570,577,'SD'],[580,588,'ND'],[590,599,'MT'],[600,629,'IL'],
  [630,658,'MO'],[660,679,'KS'],[680,693,'NE'],[700,715,'LA'],[716,729,'AR'],[730,749,'OK'],
  [750,799,'TX'],[800,816,'CO'],[820,831,'WY'],[832,838,'ID'],[840,847,'UT'],[850,865,'AZ'],
  [870,884,'NM'],[885,885,'TX'],[889,898,'NV'],[900,961,'CA'],[967,968,'HI'],[970,979,'OR'],
  [980,994,'WA'],[995,999,'AK'],
];
const STATE_TZ = {
  ME:'ET',NH:'ET',VT:'ET',MA:'ET',RI:'ET',CT:'ET',NY:'ET',NJ:'ET',PA:'ET',DE:'ET',MD:'ET',DC:'ET',
  VA:'ET',WV:'ET',NC:'ET',SC:'ET',GA:'ET',FL:'ET',OH:'ET',MI:'ET',IN:'ET',KY:'ET',PR:'ET',
  WI:'CT',IL:'CT',MN:'CT',IA:'CT',MO:'CT',AR:'CT',LA:'CT',MS:'CT',AL:'CT',TN:'CT',TX:'CT',
  OK:'CT',KS:'CT',NE:'CT',SD:'CT',ND:'CT',
  MT:'MT',WY:'MT',CO:'MT',NM:'MT',ID:'MT',UT:'MT',AZ:'MT',
  CA:'PT',NV:'PT',OR:'PT',WA:'PT', AK:'AKT', HI:'HT',
};
let resolvedState = '';
if (zipRaw.length === 5) {
  const p3 = parseInt(zipRaw.slice(0, 3), 10);
  const hit = ZIP_RANGES.find(([lo, hi]) => p3 >= lo && p3 <= hi);
  if (hit) resolvedState = hit[2];
}
let resolvedTimezone = STATE_TZ[resolvedState] || 'ET';
const resolvedZip = zipRaw.length === 5 ? zipRaw : '';

// ============================================================
// Best Contact Time — движок из DEAL CREATOR (рабочие часы 8:00–23:00 ET,
// воскресенье закрыто, "tomorrow" никогда не CALL NOW и т.д.)
// ============================================================
const ET_ZONE = 'America/New_York';
const TZ_TO_IANA = {
  ET:'America/New_York', EST:'America/New_York', EDT:'America/New_York',
  CT:'America/Chicago', CST:'America/Chicago', CDT:'America/Chicago',
  MT:'America/Denver', MST:'America/Denver', MDT:'America/Denver',
  PT:'America/Los_Angeles', PST:'America/Los_Angeles', PDT:'America/Los_Angeles',
  AKT:'America/Anchorage', AKST:'America/Anchorage', AKDT:'America/Anchorage',
  HT:'Pacific/Honolulu', HST:'Pacific/Honolulu',
};
const TZ_LABEL = {
  ET:'ET', EST:'ET', EDT:'ET', CT:'CT', CST:'CT', CDT:'CT',
  MT:'MT', MST:'MT', MDT:'MT', PT:'PT', PST:'PT', PDT:'PT',
  AKT:'AKT', AKST:'AKT', AKDT:'AKT', HT:'HT', HST:'HT',
};
const OPEN_HOUR = 8, CLOSE_HOUR = 23, CLIENT_MIN_HOUR = 7;
function clockOpenET(et) { const m = et.hour * 60 + et.minute; return m >= OPEN_HOUR * 60 && m <= CLOSE_HOUR * 60; }
function withinBusinessET(et) { if (et.weekday === 7) return false; return clockOpenET(et); }
function isValidSlot(dz) { return withinBusinessET(dz.setZone(ET_ZONE)) && dz.hour >= CLIENT_MIN_HOUR; }
function fmtDZ(dz, label) { return dz.toFormat('LLLL d, h:mma') + ' ' + label; }
function fmtET(et) { return et.toFormat('LLLL d, h:mma') + ' ET'; }
function callNow() { return { isCallNow: true, bestContactTime: 'CALL NOW', callScheduledISO: '', callScheduledPretty: 'CALL NOW', stage: 'New Deal' }; }
function scheduled(dz, et, label) { return { isCallNow: false, bestContactTime: fmtDZ(dz, label), callScheduledISO: et.toISO({ suppressMilliseconds: true }), callScheduledPretty: fmtET(et), stage: 'Call Scheduled' }; }
function resolveFuture(dz, nowET) {
  const et0 = dz.setZone(ET_ZONE);
  if (et0 > nowET && isValidSlot(dz)) return { dz, et: et0 };
  if (clockOpenET(et0) && dz.hour >= CLIENT_MIN_HOUR) {
    let d = dz;
    for (let i = 0; i < 16; i++) { d = d.plus({ days: 1 }); const et = d.setZone(ET_ZONE); if (et > nowET && isValidSlot(d)) return { dz: d, et }; }
  }
  return null;
}
function nextAtHour(nowDZ, nowET, hour, label) {
  let target = nowDZ.set({ hour, minute: 0, second: 0, millisecond: 0 });
  for (let i = 0; i < 16; i++) {
    const et = target.setZone(ET_ZONE);
    if (et > nowET && isValidSlot(target)) return scheduled(target, et, label);
    target = target.plus({ days: 1 }).set({ hour, minute: 0, second: 0, millisecond: 0 });
  }
  return callNow();
}
function ensureValidNoonAfternoon(target, nowET) {
  for (let i = 0; i < 16; i++) {
    const et = target.setZone(ET_ZONE);
    if (et > nowET && isValidSlot(target)) return { dz: target, et };
    target = target.plus({ days: 1 }).set({ hour: 12, minute: 0, second: 0, millisecond: 0 });
  }
  return { dz: target, et: target.setZone(ET_ZONE) };
}
function fromNumeric(mo, dy, yr, hour, minute, ampm, zone, nowDZ, nowET) {
  let year = yr ? (String(yr).length === 2 ? 2000 + Number(yr) : Number(yr)) : nowDZ.year;
  let hr, mn;
  if (hour != null) { hr = Number(hour) % 12; if (/p/i.test(ampm)) hr += 12; mn = Number(minute); }
  else { hr = 10; mn = 0; }
  let dz = DateTime.fromObject({ year, month: Number(mo), day: Number(dy), hour: hr, minute: mn, second: 0, millisecond: 0 }, { zone });
  if (!dz.isValid) return null;
  if (!yr && dz < nowDZ.startOf('day')) dz = dz.plus({ years: 1 });
  return resolveFuture(dz, nowET);
}
function resolveBestContactTime(parserLine, tzGeneric, now) {
  const line = (parserLine || '').trim();
  const key = (tzGeneric || 'ET').toUpperCase();
  const label = TZ_LABEL[key] || 'ET';
  const zone = TZ_TO_IANA[key] || ET_ZONE;
  const nowET = now.setZone(ET_ZONE);
  const nowDZ = now.setZone(zone);
  if (!line || /^CALL NOW$/i.test(line) || /^ANYTIME$/i.test(line)) {
    if (isValidSlot(nowDZ)) return callNow();
    return nextAtHour(nowDZ, nowET, 11, label);
  }
  if (/^AFTERNOON$/i.test(line)) {
    const h = nowDZ.hour, m = nowDZ.minute;
    let target;
    if (h < 12) target = nowDZ.set({ hour: 12, minute: 0, second: 0, millisecond: 0 });
    else if (h < 17 || (h === 17 && m <= 45)) target = nowDZ.plus({ minutes: 15 }).set({ second: 0, millisecond: 0 });
    else target = nowDZ.plus({ days: 1 }).set({ hour: 12, minute: 0, second: 0, millisecond: 0 });
    const { dz, et } = ensureValidNoonAfternoon(target, nowET);
    return scheduled(dz, et, label);
  }
  if (/^NOON$/i.test(line)) {
    const h = nowDZ.hour, m = nowDZ.minute;
    if (h < 12) { const { dz, et } = ensureValidNoonAfternoon(nowDZ.set({ hour: 12, minute: 0, second: 0, millisecond: 0 }), nowET); return scheduled(dz, et, label); }
    if (h < 14 || (h === 14 && m === 0)) return callNow();
    const { dz, et } = ensureValidNoonAfternoon(nowDZ.plus({ days: 1 }).set({ hour: 12, minute: 0, second: 0, millisecond: 0 }), nowET);
    return scheduled(dz, et, label);
  }
  const tm = line.match(/^TOMORROW(?:\s+(.+))?$/i);
  if (tm) {
    const spec = (tm[1] || '').trim();
    const early = nowDZ.hour < 9 || (nowDZ.hour === 9 && nowDZ.minute <= 50);
    const base = (early ? nowDZ : nowDZ.plus({ days: 1 })).startOf('day');
    let target;
    if (!spec) target = base.set({ hour: 10, minute: 0 });
    else if (/^NOON$/i.test(spec) || /^AFTERNOON$/i.test(spec)) target = base.set({ hour: 12, minute: 0 });
    else {
      const cm = spec.match(/^(\d{1,2}):(\d{2})\s*([AaPp][Mm])$/);
      if (cm) { let hr = Number(cm[1]) % 12; if (/p/i.test(cm[3])) hr += 12; target = base.set({ hour: hr, minute: Number(cm[2]) }); }
      else target = base.set({ hour: 10, minute: 0 });
    }
    let r = resolveFuture(target, nowET);
    if (!r) r = resolveFuture(base.set({ hour: 10, minute: 0 }), nowET);
    if (!r) r = resolveFuture(base.plus({ days: 1 }).set({ hour: 10, minute: 0 }), nowET);
    if (!r) { const fb = base.set({ hour: 10, minute: 0 }); return scheduled(fb, fb.setZone(ET_ZONE), label); }
    return scheduled(r.dz, r.et, label);
  }
  const mt = line.match(/^([A-Za-z]+)\s+(\d{1,2})(?:,\s*(\d{4}))?,\s*(\d{1,2}):(\d{2})\s*([AaPp][Mm])\s+([A-Za-z]+)$/);
  if (mt) {
    const [, month, day, yearRaw, hour, minute, ampm] = mt;
    const year = yearRaw ? Number(yearRaw) : nowDZ.year;
    let dz = DateTime.fromFormat(`${month} ${day} ${year} ${hour}:${minute} ${ampm.toUpperCase()}`, 'LLLL d yyyy h:mm a', { zone });
    if (dz.isValid) {
      if (!yearRaw && dz < nowDZ.startOf('day')) dz = dz.plus({ years: 1 });
      const r = resolveFuture(dz, nowET);
      if (!r) return callNow();
      return scheduled(r.dz, r.et, label);
    }
  }
  const num = line.match(/^(\d{1,2})[\/.\-](\d{1,2})(?:[\/.\-](\d{2,4}))?,?\s*(\d{1,2}):(\d{2})\s*([AaPp][Mm])(?:\s+[A-Za-z]+)?$/);
  if (num) { const [, mo, dy, yr, hour, minute, ampm] = num; const r = fromNumeric(mo, dy, yr, hour, minute, ampm, zone, nowDZ, nowET); if (r) return scheduled(r.dz, r.et, label); return callNow(); }
  const numNoTime = line.match(/^(\d{1,2})[\/.\-](\d{1,2})(?:[\/.\-](\d{2,4}))?(?:\s+[A-Za-z]+)?$/);
  if (numNoTime) { const [, mo, dy, yr] = numNoTime; const r = fromNumeric(mo, dy, yr, null, null, null, zone, nowDZ, nowET); if (r) return scheduled(r.dz, r.et, label); return callNow(); }
  return callNow();
}
function extractClock(text) {
  let m;
  m = text.match(/\b(\d{1,2}):(\d{2})\s*([ap])\.?\s*m?\.?\b/i); if (m) return `${Number(m[1])}:${m[2]}${m[3].toUpperCase()}M`;
  m = text.match(/\b(\d{3,4})\s*([ap])\.?\s*m?\.?\b/i);          if (m) { const d = m[1]; return `${Number(d.slice(0,-2))}:${d.slice(-2)}${m[2].toUpperCase()}M`; }
  m = text.match(/\b(\d{1,2})\s*([ap])\.?\s*m?\.?\b/i);          if (m) return `${Number(m[1])}:00${m[2].toUpperCase()}M`;
  return null;
}

// Если ZIP не дал таймзону, но клиент явно указал её в тексте времени
const rawCT = contactTime;
if (!resolvedZip && rawCT) {
  const tzm = rawCT.match(/\b(EST|EDT|CST|CDT|MST|MDT|PST|PDT|AKST|AKDT|HST|ET|CT|MT|PT|AKT|HT)\b/i);
  const wordm = rawCT.match(/\b(eastern|central|mountain|pacific|alaska|hawaii)\b/i);
  const WORD = { eastern:'ET', central:'CT', mountain:'MT', pacific:'PT', alaska:'AKT', hawaii:'HT' };
  if (tzm) resolvedTimezone = TZ_LABEL[tzm[1].toUpperCase()] || resolvedTimezone;
  else if (wordm) resolvedTimezone = WORD[wordm[1].toLowerCase()];
}

// Формируем parserLine из сырого текста формы (вместо AI-парсера)
let parserLine = '';
if (/\b(tomorrow|mañana|manana)\b/i.test(rawCT)) {
  const clk = extractClock(rawCT);
  parserLine = clk ? `TOMORROW ${clk}` : 'TOMORROW';
} else if (/\bafternoon\b/i.test(rawCT)) {
  parserLine = 'AFTERNOON';
} else if (/\bnoon\b/i.test(rawCT)) {
  parserLine = 'NOON';
} else if (rawCT) {
  const saysNow = /\b(now|asap|right now|immediately|any\s?time|whenever|all day|ahora|ya|cuando\s+sea|cuando\s+quieras|cualquier\s+hora|no\s+importa|lo\s+antes\s+posible)\b/i.test(rawCT);
  if (!saysNow) {
    const clk = extractClock(rawCT);
    const dm  = rawCT.match(/\b(\d{1,2})[\/.\-](\d{1,2})(?:[\/.\-](\d{2,4}))?\b/);
    if (dm) {
      const datePart = `${Number(dm[1])}/${Number(dm[2])}${dm[3] ? '/' + dm[3] : ''}`;
      parserLine = clk ? `${datePart} ${clk}` : datePart;
    } else if (clk) {
      const zoneNow = DateTime.now().setZone(TZ_TO_IANA[(resolvedTimezone || 'ET').toUpperCase()] || ET_ZONE);
      parserLine = `${zoneNow.month}/${zoneNow.day} ${clk}`;
    }
  }
}
const t = resolveBestContactTime(parserLine, resolvedTimezone, DateTime.now());

return [{
  json: {
    valid: true,
    firstName, lastName,
    fullName: (firstName + ' ' + lastName).trim(),
    phone, phoneForCall: phone, phoneLast10: phoneNational,
    phoneSearchVariants, phoneSearchRawCriteria, phoneSearchCriteria,
    isInternational,
    email, city,
    resolvedZip,
    resolvedCity: city || resolvedState,
    resolvedState, resolvedTimezone,
    contactTime,
    bestContactTime: t.bestContactTime,
    callScheduledISO: t.callScheduledISO,
    callScheduledPretty: t.callScheduledPretty,
    stage: t.stage,
    source, interest, notes, language,
    submittedAt: DateTime.now().setZone(ET_ZONE).toFormat('yyyy-MM-dd HH:mm'),
  },
}];

// Решение по контакту: нашли по телефону -> обновляем, нет -> создаём (upsert по Phone)
const prev = $('Validate & Normalize').first().json;
const searchResult = $input.first().json || {};
const contacts = searchResult.data || [];
const existingContactId = contacts.length > 0 ? contacts[0].id : null;

const contactData = { Owner: { id: '5212466000034327806' } };
if (existingContactId) contactData.id = existingContactId;
if (prev.firstName) contactData.First_Name = prev.firstName;
contactData.Last_Name = prev.lastName || prev.fullName || 'Unknown';
if (prev.phone) contactData.Phone = prev.phone;
if (prev.email) contactData.Email = prev.email;
if (prev.source) contactData.Lead_Source = prev.source;
if (prev.bestContactTime) contactData.Best_Contact_Time = prev.bestContactTime;
if (prev.resolvedTimezone) contactData.Client_Timezone = prev.resolvedTimezone;
if (prev.resolvedZip) contactData.Mailing_Zip = prev.resolvedZip;
if (prev.resolvedCity && prev.resolvedCity !== 'Not available') contactData.Mailing_State = prev.resolvedCity;
if (prev.language) { contactData.Preferred_Language = prev.language; contactData.Language = prev.language; }
if (prev.contactTime) contactData.Contact_Time_Raw = prev.contactTime;
const desc = [prev.interest ? 'Interest: ' + prev.interest : '', prev.notes ? 'Notes: ' + prev.notes : ''].filter(Boolean).join('\n');
if (desc) contactData.Description = desc;

return [{ json: { ...prev, existingContactId, contactData } }];

// Достаём ID контакта из ответа Zoho (или берём найденный ранее)
const zohoResponse = $input.first().json || {};
const prev = $('Contact Decision').first().json;
let contactId = prev.existingContactId;
if (!contactId) {
  const data = zohoResponse.data || [];
  if (data.length > 0) contactId = data[0].details?.id || data[0].id || null;
}
return [{ json: { ...prev, zohoContactId: contactId } }];

// Дедупликация сделки (окно 2 дня, Stage "Duplicates / Junk" пропускаем) — логика DEAL CREATOR
const prev = $('Extract Contact ID').first().json;
const searchResult = $input.first().json || {};
const deals = searchResult.data || [];
const now = new Date();
const twoDaysMs = 2 * 24 * 60 * 60 * 1000;

let existingDealId = null;
let dealAction = 'create';
let existingDealOwner = null;
for (const deal of deals) {
  if (deal.Stage === 'Duplicates / Junk') continue;
  const diffMs = now.getTime() - new Date(deal.Created_Time).getTime();
  if (diffMs < twoDaysMs) {
    existingDealId = deal.id;
    dealAction = 'update';
    existingDealOwner = deal.Owner ? (deal.Owner.name || null) : null;
    break;
  }
}
const isDuplicate = dealAction === 'update';
const stage = prev.stage || 'New Deal';

const dealData = {};
if (dealAction === 'update' && existingDealId) dealData.id = existingDealId;
if (dealAction === 'create') dealData.Deal_Name = prev.fullName || 'Unknown';
dealData.Stage = stage;
if (prev.source) dealData.Lead_Source = prev.source;
if (prev.bestContactTime) dealData.Best_Contact_Time = prev.bestContactTime;
if (prev.resolvedTimezone) { dealData.Client_Timezone = prev.resolvedTimezone; dealData.Timezone = prev.resolvedTimezone; }
if (prev.contactTime) dealData.Contact_Time_Raw = prev.contactTime;
if (prev.phone) dealData.Phone = prev.phone;
if (prev.zohoContactId) dealData.Contact_Name = { id: prev.zohoContactId };
if (prev.callScheduledISO) dealData.Call_Scheduled_Date_Time = prev.callScheduledISO;
if (prev.resolvedZip) dealData.Zip_Code = prev.resolvedZip;
if (prev.language) dealData.Language = prev.language;
const desc = [prev.interest ? 'Interest: ' + prev.interest : '', prev.notes ? 'Notes: ' + prev.notes : ''].filter(Boolean).join('\n');
if (desc) dealData.Description = desc;
dealData.Pipeline = 'Standard';
// Deal Owner всегда Ariel — как в DEAL CREATOR
dealData.Owner = { id: '5212466000034327806' };

return [{
  json: {
    ...prev,
    existingDealId, dealAction, isDuplicate, existingDealOwner, dealData,
    zohoBody: JSON.stringify({ data: [dealData] }),
  },
}];

// Строка журнала для Google Sheet (лист "Dashboard Leads")
const prev = $('Deal Decision').first().json;
const dealResp = $input.first().json || {};
const dealId = (dealResp.data && dealResp.data[0] && dealResp.data[0].details && dealResp.data[0].details.id) || prev.existingDealId || '';

return [{
  json: {
    'Added': DateTime.now().setZone('America/New_York').toFormat('yyyy-MM-dd HH:mm'),
    'First Name': prev.firstName || '',
    'Last Name': prev.lastName || '',
    'Phone': prev.phone || '',
    'Email': prev.email || '',
    'City': prev.resolvedCity || '',
    'ZIP': prev.resolvedZip || '',
    'Contact Time': prev.contactTime || '',
    'Best Contact Time': prev.bestContactTime || '',
    'Source': prev.source || 'Dashboard',
    'Interest': prev.interest || '',
    'Notes': prev.notes || '',
    'Status': prev.isDuplicate ? 'Duplicate (updated)' : 'New',
    'Deal Stage': (prev.dealData && prev.dealData.Stage) || '',
    'Deal ID': String(dealId),
    'Contact ID': String(prev.zohoContactId || ''),
  },
}];
